using System;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Security.Cryptography;
using System.Collections.Generic;

namespace PdfGen.Core
{
    public sealed class PdfRenderConfig
    {
        public string WkhtmlPath { get; set; }
        public string TempDirectory { get; set; }
        public string DefaultPageSize { get; set; } = "A4";
        public int TimeoutMs { get; set; } = 30000;
        public bool EnableJavaScript { get; set; } = false;
        public Dictionary<string, string> ExtraHeaders { get; set; } = new();
    }

    public interface IConfigResolver
    {
        PdfRenderConfig Resolve();
    }

    public class EnvironmentConfigResolver : IConfigResolver
    {
        private static readonly Regex SafePathPattern = new(@"^[a-zA-Z]:\\[\w\\\-\.]+$|^/[\w/\-\.]+$", RegexOptions.Compiled);

        public PdfRenderConfig Resolve()
        {
            var config = new PdfRenderConfig
            {
                WkhtmlPath = ResolveExecutablePath(),
                TempDirectory = ResolveTempDir(),
                DefaultPageSize = Environment.GetEnvironmentVariable("PDFGEN_PAGE_SIZE") ?? "A4",
                TimeoutMs = int.TryParse(Environment.GetEnvironmentVariable("PDFGEN_TIMEOUT"), out var t) ? t : 30000,
                EnableJavaScript = Environment.GetEnvironmentVariable("PDFGEN_ENABLE_JS") == "1"
            };
            return config;
        }

        private string ResolveExecutablePath()
        {
            var envPath = Environment.GetEnvironmentVariable("PDFGEN_WKHTML_PATH");
            if (!string.IsNullOrEmpty(envPath) && SafePathPattern.IsMatch(envPath))
                return envPath;
            if (OperatingSystem.IsWindows())
                return @"C:\Program Files\wkhtmltopdf\bin\wkhtmltopdf.exe";
            return "/usr/local/bin/wkhtmltopdf";
        }

        private string ResolveTempDir()
        {
            var envDir = Environment.GetEnvironmentVariable("PDFGEN_TEMP_DIR");
            if (!string.IsNullOrEmpty(envDir) && SafePathPattern.IsMatch(envDir) && Directory.Exists(envDir))
                return envDir;
            return Path.GetTempPath();
        }
    }

    public class PdfArgumentBuilder
    {
        private readonly PdfRenderConfig _config;
        private readonly List<string> _args = new();

        public PdfArgumentBuilder(PdfRenderConfig config)
        {
            _config = config;
        }

        public PdfArgumentBuilder WithPageSize(string pageSize)
        {
            var sanitized = SanitizePageSize(pageSize ?? _config.DefaultPageSize);
            _args.Add($"--page-size {sanitized}");
            return this;
        }

        public PdfArgumentBuilder WithMargins(string top, string right, string bottom, string left)
        {
            _args.Add($"--margin-top {SanitizeMargin(top)}");
            _args.Add($"--margin-right {SanitizeMargin(right)}");
            _args.Add($"--margin-bottom {SanitizeMargin(bottom)}");
            _args.Add($"--margin-left {SanitizeMargin(left)}");
            return this;
        }

        public PdfArgumentBuilder WithTitle(string title)
        {
            if (!string.IsNullOrWhiteSpace(title))
            {
                var safe = Regex.Replace(title, @"[^\w\s\-\.]", "");
                _args.Add($"--title \"{safe}\"");
            }
            return this;
        }

        public PdfArgumentBuilder WithHeaders()
        {
            foreach (var header in _config.ExtraHeaders)
            {
                var key = Regex.Replace(header.Key, @"[^\w\-]", "");
                var val = Regex.Replace(header.Value, @"[^\w\s\-\./=]", "");
                _args.Add($"--custom-header {key} \"{val}\"");
            }
            return this;
        }

        public string Build(string inputPath, string outputPath)
        {
            var sb = new StringBuilder();
            if (!_config.EnableJavaScript)
                sb.Append("--disable-javascript ");
            foreach (var arg in _args)
                sb.Append(arg + " ");
            sb.Append($"\"{inputPath}\" \"{outputPath}\"");
            return sb.ToString();
        }

        private static string SanitizePageSize(string input)
        {
            var allowed = new HashSet<string> { "A4", "A3", "Letter", "Legal", "Tabloid" };
            return allowed.Contains(input) ? input : "A4";
        }

        private static string SanitizeMargin(string input)
        {
            if (string.IsNullOrEmpty(input)) return "10mm";
            if (Regex.IsMatch(input, @"^\d{1,3}(mm|cm|in|px)$"))
                return input;
            return "10mm";
        }
    }

    public class PdfGenerationService
    {
        private readonly IConfigResolver _configResolver;

        public PdfGenerationService(IConfigResolver configResolver)
        {
            _configResolver = configResolver;
        }

        public byte[] GenerateFromHtml(string htmlContent, string title = null, string pageSize = null)
        {
            var config = _configResolver.Resolve();
            var inputFile = Path.Combine(config.TempDirectory, $"{Guid.NewGuid():N}.html");
            var outputFile = Path.Combine(config.TempDirectory, $"{Guid.NewGuid():N}.pdf");

            try
            {
                File.WriteAllText(inputFile, htmlContent, Encoding.UTF8);

                var argBuilder = new PdfArgumentBuilder(config)
                    .WithPageSize(pageSize)
                    .WithMargins("10mm", "10mm", "10mm", "10mm")
                    .WithTitle(title)
                    .WithHeaders();

                var arguments = argBuilder.Build(inputFile, outputFile);
                ExecuteRenderer(config, arguments);

                if (!File.Exists(outputFile))
                    throw new InvalidOperationException("PDF generation failed - no output file");

                return File.ReadAllBytes(outputFile);
            }
            finally
            {
                SafeDelete(inputFile);
                SafeDelete(outputFile);
            }
        }

        private void ExecuteRenderer(PdfRenderConfig config, string arguments)
        {
            var startInfo = new ProcessStartInfo
            {
                FileName = config.WkhtmlPath,
                Arguments = arguments,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                CreateNoWindow = true
            };

            ApplyEnvironmentOverrides(startInfo);

            using var process = Process.Start(startInfo);
            if (process == null)
                throw new InvalidOperationException("Failed to start renderer process");

            process.WaitForExit(config.TimeoutMs);
            if (!process.HasExited)
            {
                process.Kill(true);
                throw new TimeoutException("PDF rendering timed out");
            }

            if (process.ExitCode != 0)
            {
                var stderr = process.StandardError.ReadToEnd();
                throw new InvalidOperationException($"Renderer exited with code {process.ExitCode}: {stderr}");
            }
        }

        private void ApplyEnvironmentOverrides(ProcessStartInfo startInfo)
        {
            var display = Environment.GetEnvironmentVariable("PDFGEN_DISPLAY");
            if (!string.IsNullOrEmpty(display) && Regex.IsMatch(display, @"^:\d{1,2}(\.\d)?$"))
                startInfo.Environment["DISPLAY"] = display;

            var fontConfig = Environment.GetEnvironmentVariable("PDFGEN_FONTCONFIG_PATH");
            if (!string.IsNullOrEmpty(fontConfig) && Regex.IsMatch(fontConfig, @"^/[\w/\-\.]+$") && Directory.Exists(fontConfig))
                startInfo.Environment["FONTCONFIG_PATH"] = fontConfig;
        }

        private static void SafeDelete(string path)
        {
            try { if (File.Exists(path)) File.Delete(path); } catch { }
        }
    }
}
